400	// TestEveryConclusionTouchesOnlyWhatItDeclares keeps `amends` honest, the way
401	// TestEveryStageProducesWhatItDeclares does for `produces`: a stage's conclude
402	// may rewrite the rows it names and no other, and a stage that concludes nothing
403	// declares nothing. The results it works on are never changed under the caller
404	// either (clone is shallow, so a fact slice is shared).
405	func TestEveryConclusionTouchesOnlyWhatItDeclares(t *testing.T) {
406		state, roots := buildChain(t, chainOpts{dnsNames: []string{"example.com"}, withIntermediate: true})
407		for _, tc := range []struct {
408			name string
409			tg   Target
410			env  Env
411		}{
412			{"a failed resolution behind a proxy", target(),
413				fakeEnv{resolve: resolveFailing(errNoSuchHost), proxy: proxiedBoth}},
414			{"an empty answer behind a proxy", target(), fakeEnv{resolve: resolveEmpty, proxy: proxiedBoth}},
415			{"a misbehaving resolver behind a proxy", target(),
416				fakeEnv{resolve: resolveFailing(misbehavingErr()), proxy: proxiedBoth}},
417			{"a successful run behind a proxy", target(),
418				fakeEnv{proxy: proxiedBoth, roots: roots, handshake: handshakeReturning(state)}},
419			{"a literal address behind a proxy", Target{Host: "10.2.3.4", Port: 443}, fakeEnv{proxy: proxiedBoth}},
420			{"a failed resolution without a proxy", target(), fakeEnv{resolve: resolveFailing(errNoSuchHost)}},
421		} {
422			t.Run(tc.name, func(t *testing.T) {
423				full := runAll(t, tc.env, tc.tg)
424				snapshot := make([]Check, len(full.All()))
425				for i, c := range full.All() {
426					c.Facts = slices.Clone(c.Facts)
427					snapshot[i] = c
428				}
429	
430				var concluding int
431				for _, s := range stages() {
432					if s.conclude == nil {
433						if s.amends != nil {
434							t.Errorf("stage %q declares amends %v but has no conclude", s.id, s.amends)
435						}
436						continue
437					}
438					concluding++
439					if len(s.amends) == 0 {
440						t.Errorf("stage %q concludes but declares no amends", s.id)
441					}
442					amended := map[CheckID]bool{}
443					for _, id := range s.amends {
444						amended[id] = true
445					}
446	
447					work := full.clone()
448					s.conclude(tc.tg, &work)
449	
450					if len(work.All()) != len(snapshot) {
451						t.Fatalf("stage %q: conclude changed the number of checks from %d to %d",
452							s.id, len(snapshot), len(work.All()))
453					}
454					for i, c := range work.All() {
455						if c.ID != snapshot[i].ID {
456							t.Errorf("stage %q: conclude moved %q to position %d", s.id, c.ID, i)
457						}
458						if !amended[c.ID] && !reflect.DeepEqual(c, snapshot[i]) {
459							t.Errorf("stage %q: conclude changed %q, which it does not declare: %+v, was %+v",
460								s.id, c.ID, c, snapshot[i])
461						}
462					}
463					if !reflect.DeepEqual(full.All(), snapshot) {
464						t.Errorf("stage %q: conclude wrote into the results it was cloned from", s.id)
465					}
466				}
467				if concluding == 0 {
468					t.Error("no stage declares a conclusion: the Proxy stage must conclude on the DNS row")
469				}
470			})
471		}
472	
473		t.Run("the proxy stage amends the DNS row", func(t *testing.T) {
474			for _, s := range stages() {
475				if s.id != StageProxy {
476					continue
477				}
478				if s.conclude == nil || !slices.Equal(s.amends, []CheckID{CheckResolve}) {
479					t.Errorf("the proxy stage concludes with amends %v (conclude set: %v), want [resolve]",
480						s.amends, s.conclude != nil)
481				}
482			}
483		})
484	}
