81			{"an unknown name", resolveFailing(errNoSuchHost), "", proxiedBoth,
82				[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
83			{"an empty answer carries no error fact", resolveEmpty, "", proxiedBoth,
84				[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}}},
85			{"a proxy for https only", resolveFailing(errNoSuchHost), "", perScheme(
