324	// The conclusion builds a new slice of facts. The previous Results shares
325	// backing arrays with the copy RunStep works on (clone is shallow), and a caller
326	// may hold it across a goroutine boundary: an append into a slice with spare
327	// capacity would write into it.
328	func TestTheConclusionDoesNotWriteIntoPrior(t *testing.T) {
329		env := fakeEnv{resolve: resolveFailing(errNoSuchHost), proxy: proxiedBoth}
330		generic := RunStep(context.Background(), target(), env, DefaultSettings(), StageResolve, Results{})
331	
332		checks := slices.Clone(generic.All())
333		spare := make([]Fact, 2, 8)
334		copy(spare, checks[0].Facts)
335		checks[0].Facts = spare
336		prior := ResultsOf(checks...)
337	
338		wantFacts := slices.Clone(spare)
339		wantSummary, wantReason := checks[0].Summary, checks[0].Reason
340	
341		next := RunStep(context.Background(), target(), env, DefaultSettings(), StageProxy, prior)
342	
343		// The premise: the step did rewrite its own copy.
344		if c := resolveRowOf(t, next); c.Reason != ReasonDirectResolveFailedProxyConfigured {
345			t.Fatalf("premise: the new row reason = %q, want %q", c.Reason, ReasonDirectResolveFailedProxyConfigured)
346		}
347	
348		got := resolveRowOf(t, prior)
349		if !slices.Equal(got.Facts, wantFacts) || got.Summary != wantSummary || got.Reason != wantReason {
350			t.Errorf("prior row = %q (reason %q) %v, want %q (reason %q) %v untouched",
351				got.Summary, got.Reason, got.Facts, wantSummary, wantReason, wantFacts)
352		}
353		if spare := got.Facts[:cap(got.Facts)]; spare[2] != (Fact{}) {
354			t.Errorf("the spare capacity of the prior facts was written: %v", spare)
355		}
356	}
