15	// DEVDESK-596: when the direct lookup of a named target fails and the Proxy row
16	// says a proxy applies, the DNS row is rewritten in place once the Proxy stage
17	// has run. Behind a mandatory proxy the name is often resolved by the proxy, so
18	// "does not resolve" alone would mislead. The Proxy stage keeps its place in the
19	// pipeline; it concludes on the earlier DNS row through stage.conclude.
20	
21	const (
22		resolveGenericSummary = "example.com does not resolve"
23		resolveProxySummary   = "example.com does not resolve directly; a proxy is configured for this target"
24		proxyDisplay          = "http://proxy.corp:3128"
25	)
26	
27	func resolveFailing(err error) func(context.Context, string, string) ([]net.IP, error) {
28		return func(context.Context, string, string) ([]net.IP, error) { return nil, err }
29	}
30	
31	func resolveEmpty(context.Context, string, string) ([]net.IP, error) { return nil, nil }
32	
33	var errNoSuchHost = errors.New("no such host")
34	
35	// misbehavingErr is the DNS error that keeps its own reason.
36	func misbehavingErr() *net.DNSError {
37		return &net.DNSError{Err: "server misbehaving", Name: "example.com", IsTemporary: true}
38	}
39	
40	// resolveRowOf returns the DNS row of a finished run.
41	func resolveRowOf(t *testing.T, res Results) Check {
42		t.Helper()
43		return checkNamed(t, res.All(), CheckResolve)
44	}
45	
46	func runAll(t *testing.T, env Env, tg Target) Results {
47		t.Helper()
48		res, err := Run(context.Background(), tg, env, DefaultSettings())
49		if err != nil {
50			t.Fatalf("Run: %v", err)
51		}
52		return res
53	}
54	
55	// chain runs every stage through RunStep, the way a view does.
56	func chain(env Env, tg Target) Results {
57		var res Results
58		for _, id := range Steps() {
59			res = RunStep(context.Background(), tg, env, DefaultSettings(), id, res)
60		}
61		return res
62	}
