70	// Every way the Proxy row reads "configured" rewrites a failed lookup the same
71	// way. The Proxy fact is the displayed proxy only (https first), the Resolver and
72	// Error facts are kept, and the verdict stays Fail: the direct lookup did fail.
73	func TestAFailedResolutionWithAProxyConfiguredSaysSo(t *testing.T) {
74		for _, tc := range []struct {
75			name     string
76			resolve  func(context.Context, string, string) ([]net.IP, error)
77			resolver string
78			proxy    func(*url.URL) netproxy.Decision
79			want     []Fact
80		}{
81			{"an unknown name", resolveFailing(errNoSuchHost), "", proxiedBoth,
82				[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
83			{"an empty answer carries no error fact", resolveEmpty, "", proxiedBoth,
84				[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}}},
85			{"a proxy for https only", resolveFailing(errNoSuchHost), "", perScheme(
86				decided(netproxy.DecisionProxied, "HTTPS_PROXY", proxyDisplay), none()),
87				[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
88			{"a proxy for http only", resolveFailing(errNoSuchHost), "", perScheme(
89				none(), decided(netproxy.DecisionProxied, "http_proxy", proxyDisplay)),
90				[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
91			{"two different proxys: the https one", resolveFailing(errNoSuchHost), "", perScheme(
92				decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://a:3128"),
93				decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://b:8080")),
94				[]Fact{{"Resolver", "System resolver"}, {"Proxy", "http://a:3128"}, {"Error", "no such host"}}},
95			{"a proxy outranks an exclusion on the other scheme", resolveFailing(errNoSuchHost), "", perScheme(
96				decided(netproxy.DecisionExcluded, "HTTPS_PROXY", ""),
97				decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://b:8080")),
98				[]Fact{{"Resolver", "System resolver"}, {"Proxy", "http://b:8080"}, {"Error", "no such host"}}},
99			{"a proxy outranks loopback on the other scheme", resolveFailing(errNoSuchHost), "", perScheme(
100				decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://a:3128"),
101				decided(netproxy.DecisionLoopback, "HTTP_PROXY", "")),
102				[]Fact{{"Resolver", "System resolver"}, {"Proxy", "http://a:3128"}, {"Error", "no such host"}}},
103			{"an invalid variable and a proxied scheme still name the proxy", resolveFailing(errNoSuchHost), "", perScheme(
104				decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""),
105				decided(netproxy.DecisionProxied, "HTTP_PROXY", proxyDisplay)),
106				[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
107			{"a named resolver is kept", resolveFailing(errNoSuchHost), "9.9.9.9", proxiedBoth,
108				[]Fact{{"Resolver", "9.9.9.9"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
109		} {
110			t.Run(tc.name, func(t *testing.T) {
111				tg := Target{Host: "example.com", Port: 443, Resolver: tc.resolver}
112				res := runAll(t, fakeEnv{resolve: tc.resolve, proxy: tc.proxy}, tg)
113	
114				// The premise: the Proxy row reads that a proxy applies.
115				if p := checkNamed(t, res.All(), CheckProxy); p.Proxy == "" {
116					t.Fatalf("premise: the proxy row names no proxy (reason %q)", p.Reason)
117				}
118	
119				c := resolveRowOf(t, res)
120				if c.Summary != resolveProxySummary {
121					t.Errorf("summary = %q, want %q", c.Summary, resolveProxySummary)
122				}
123				if c.Verdict != Fail {
124					t.Errorf("verdict = %v, want Fail: the direct lookup did fail", c.Verdict)
125				}
126				if c.Reason != ReasonDirectResolveFailedProxyConfigured {
127					t.Errorf("reason = %q, want %q", c.Reason, ReasonDirectResolveFailedProxyConfigured)
128				}
129				if !slices.Equal(c.Facts, tc.want) {
130					t.Errorf("facts = %v, want %v", c.Facts, tc.want)
131				}
132				if c.ID != CheckResolve || c.Stage != StageResolve || c.Title != "DNS resolution" {
133					t.Errorf("identity = %s/%s/%q, want the row's own", c.ID, c.Stage, c.Title)
134				}
135			})
136		}
137	}
