139	// Without a proxy that applies, the DNS row is what it was before: strictly the
140	// row of a run in which no proxy variable exists.
141	func TestAFailedResolutionWithoutAProxyIsUnchanged(t *testing.T) {
142		failures := []struct {
143			name    string
144			resolve func(context.Context, string, string) ([]net.IP, error)
145		}{
146			{"an unknown name", resolveFailing(errNoSuchHost)},
147			{"an empty answer", resolveEmpty},
148			{"a misbehaving resolver", resolveFailing(misbehavingErr())},
149		}
150		for _, tc := range []struct {
151			name  string
152			proxy func(*url.URL) netproxy.Decision
153		}{
154			{"no variable", perScheme(none(), none())},
155			{"NO_PROXY names the target on both schemes", perScheme(
156				decided(netproxy.DecisionExcluded, "HTTPS_PROXY", ""),
157				decided(netproxy.DecisionExcluded, "HTTP_PROXY", ""))},
158			{"a loopback target", perScheme(
159				decided(netproxy.DecisionLoopback, "HTTPS_PROXY", ""),
160				decided(netproxy.DecisionLoopback, "HTTP_PROXY", ""))},
161			{"an invalid variable on https only", perScheme(decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""), none())},
162			{"an invalid variable on http only", perScheme(none(), decided(netproxy.DecisionInvalid, "HTTP_PROXY", ""))},
163			{"both variables invalid", perScheme(
164				decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""),
165				decided(netproxy.DecisionInvalid, "HTTP_PROXY", ""))},
166		} {
167			for _, f := range failures {
168				t.Run(tc.name+", "+f.name, func(t *testing.T) {
169					reference := resolveRowOf(t, runAll(t, fakeEnv{resolve: f.resolve}, target()))
170					got := resolveRowOf(t, runAll(t, fakeEnv{resolve: f.resolve, proxy: tc.proxy}, target()))
171	
172					if !reflect.DeepEqual(got, reference) {
173						t.Errorf("row = %+v, want the row of a run without a proxy: %+v", got, reference)
174					}
175					if got.Reason == ReasonDirectResolveFailedProxyConfigured || factValue(got, "Proxy") != "" {
176						t.Errorf("row %+v mentions a proxy that does not apply", got)
177					}
178				})
179			}
180		}
181	}
