183	// Rewriting the DNS row changes nothing else: same checks in the same order, the
184	// Proxy row says what it said, and everything below the failed resolution is
185	// still blocked by it.
186	func TestTheRestOfTheRunIsUnchangedBehindAProxy(t *testing.T) {
187		plain := runAll(t, fakeEnv{resolve: resolveFailing(errNoSuchHost)}, target())
188		behind := runAll(t, fakeEnv{resolve: resolveFailing(errNoSuchHost), proxy: proxiedBoth}, target())
189	
190		if got, want := idsOf(behind.All()), idsOf(plain.All()); !slices.Equal(got, want) {
191			t.Fatalf("checks = %v, want %v, the same order as without a proxy", got, want)
192		}
193		if got := resolveRowOf(t, behind); got.Reason != ReasonDirectResolveFailedProxyConfigured {
194			t.Fatalf("premise: the DNS row reason = %q, want %q", got.Reason, ReasonDirectResolveFailedProxyConfigured)
195		}
196	
197		p := checkNamed(t, behind.All(), CheckProxy)
198		if p.Verdict != Info || p.Summary != "Configured for this target: "+proxyDisplay {
199			t.Errorf("proxy row = %v %q, want INFO and the configured summary", p.Verdict, p.Summary)
200		}
201		if got := factValue(p, "HTTPS"); got != proxyDisplay+" (HTTPS_PROXY)" {
202			t.Errorf("HTTPS fact = %q", got)
203		}
204		if got := factValue(p, "HTTP"); got != proxyDisplay+" (HTTP_PROXY)" {
205			t.Errorf("HTTP fact = %q", got)
206		}
207	
208		for _, id := range []CheckID{
209			CheckRoute, CheckICMP, CheckTCP,
210			CheckTLSHandshake, CheckTLSChain, CheckTLSHostname, CheckTLSExpiry, CheckTLSVersion, CheckHTTP,
211		} {
212			c := checkNamed(t, behind.All(), id)
213			if c.Verdict != NotApplicable || c.Because != CheckResolve {
214				t.Errorf("%s = %v because %q, want N/A because %q", id, c.Verdict, c.Because, CheckResolve)
215			}
216			if want := "Skipped — DNS resolution did not succeed"; c.Summary != want {
217				t.Errorf("%s summary = %q, want %q", id, c.Summary, want)
218			}
219			if ref := checkNamed(t, plain.All(), id); !reflect.DeepEqual(c, ref) {
220				t.Errorf("%s = %+v, want the row of a run without a proxy: %+v", id, c, ref)
221			}
222		}
223	
224		rev := checkNamed(t, behind.All(), CheckReverseDNS)
225		if rev.Verdict != NotApplicable || rev.Because != "" || rev.Summary != "Target is a name, not an address" {
226			t.Errorf("reverse DNS = %v because %q %q, want N/A with its own summary", rev.Verdict, rev.Because, rev.Summary)
227		}
228	
229		if got := Summarize(behind.All()); got != Fail {
230			t.Errorf("Summarize = %v, want Fail", got)
231		}
232	}
