295	// Run and a chain of RunStep give the same rows, and the conclusion arrives with
296	// the Proxy stage and not before: after the resolve stage alone the row is the
297	// generic one. The DNS row never changes position.
298	func TestRunStepChainMatchesRunBehindAProxy(t *testing.T) {
