304			t.Errorf("chain = %+v\nRun   = %+v", piecewise.All(), whole.All())
305		}
306	
307		afterResolve := RunStep(context.Background(), target(), env, DefaultSettings(), StageResolve, Results{})
308		if c := resolveRowOf(t, afterResolve); c.Summary != resolveGenericSummary || c.Reason != "" {
309			t.Errorf("after the resolve stage: %q (reason %q), want the generic conclusion", c.Summary, c.Reason)
310		}
