312		afterProxy := RunStep(context.Background(), target(), env, DefaultSettings(), StageProxy, afterResolve)
313		if c := resolveRowOf(t, afterProxy); c.Summary != resolveProxySummary || c.Reason != ReasonDirectResolveFailedProxyConfigured {
314			t.Errorf("after the proxy stage: %q (reason %q), want the rewritten conclusion", c.Summary, c.Reason)
315		}
316		if ids := idsOf(afterProxy.All()); !slices.Equal(ids, []CheckID{CheckResolve, CheckReverseDNS, CheckProxy}) {
317			t.Errorf("checks = %v, want the DNS row still first, in place", ids)
