438	// The conclusion acts only when all its premises hold. Called directly, it
439	// leaves the results alone when the DNS row is missing or did not fail, or when
440	// the Proxy row names no proxy; the control shows it rewrites when they hold.
441	func TestTheConclusionNeedsItsPremises(t *testing.T) {
442		dns := func(v Verdict) Check {
443			return Check{ID: CheckResolve, Stage: StageResolve, Title: "DNS resolution", Verdict: v,
444				Summary: resolveGenericSummary, Facts: []Fact{{"Resolver", "System resolver"}, {"Error", "no such host"}}}
445		}
446		proxied := Check{ID: CheckProxy, Stage: StageProxy, Verdict: Info, Reason: ReasonProxyConfigured, Proxy: proxyDisplay}
447		unproxied := Check{ID: CheckProxy, Stage: StageProxy, Verdict: NotApplicable, Reason: ReasonProxyNone}
448	
449		for _, tc := range []struct {
450			name   string
451			checks []Check
452			want   bool // rewritten
453		}{
454			{"every premise holds", []Check{dns(Fail), proxied}, true},
455			{"no DNS row", []Check{proxied}, false},
456			{"a DNS row that passed", []Check{dns(OK), proxied}, false},
457			{"a DNS row that does not apply", []Check{dns(NotApplicable), proxied}, false},
458			{"no proxy row", []Check{dns(Fail)}, false},
459			{"a proxy row without a proxy", []Check{dns(Fail), unproxied}, false},
460		} {
461			t.Run(tc.name, func(t *testing.T) {
462				res := ResultsOf(tc.checks...)
463				before := slices.Clone(res.All())
464	
465				concludeResolveBehindProxy(target(), &res)
466	
