188	// produced runs the battery and returns every check it observed.
189	func produced(t *testing.T) []Check {
190		t.Helper()
191		var all []Check
192		for _, s := range batteries(t) {
193			res, err := Run(context.Background(), s.tg, s.env, DefaultSettings())
194			if err != nil {
195				t.Fatalf("%s: %v", s.name, err)
196			}
197			all = append(all, res.All()...)
198		}
199		return all
200	}
