228	// TestNoGuidanceRowIsUnreachable catches the other drift: a row written for a
229	// combination no stage produces. It is dead text that reads as coverage.
230	func TestNoGuidanceRowIsUnreachable(t *testing.T) {
231		type key struct {
232			id     CheckID
233			v      Verdict
234			reason Reason
235		}
236		seen := map[key]bool{}
237		for _, c := range produced(t) {
238			seen[key{c.ID, c.Verdict, c.Reason}] = true
239		}
240	
241		for _, g := range explanations {
242			if g.reason != "" {
243				if !seen[key{g.check, g.verdict, g.reason}] {
244					t.Errorf("guidance for %s/%s/%s is unreachable — no scenario produces it",
245						g.check, g.verdict, g.reason)
246				}
247				continue
248			}
249			// A reason-less row is reached by any reason for that verdict.
250			found := false
251			for k := range seen {
252				if k.id == g.check && k.v == g.verdict {
253					found = true
254				}
255			}
256			if !found {
257				t.Errorf("guidance for %s/%s is unreachable — no scenario produces it", g.check, g.verdict)
258			}
259		}
260	}
