288	// TestTheMostSpecificGuidanceWins is why Reason exists: one Fail, three jobs.
289	func TestTheMostSpecificGuidanceWins(t *testing.T) {
290		texts := map[Reason]string{}
291		for _, r := range []Reason{ReasonSelfSigned, ReasonNoIntermediates, ReasonUntrustedRoot} {
292			e := Explain(Check{ID: CheckTLSChain, Verdict: Fail, Reason: r})
293			if e.Means == "" {
294				t.Fatalf("no guidance for chain/%s", r)
295			}
296			texts[r] = e.Do
297		}
298		if texts[ReasonSelfSigned] == texts[ReasonNoIntermediates] ||
299			texts[ReasonSelfSigned] == texts[ReasonUntrustedRoot] ||
300			texts[ReasonNoIntermediates] == texts[ReasonUntrustedRoot] {
301			t.Fatal("the three chain failures share advice; they are three different jobs")
302		}
303	}
