359	// TestTheBatteriesReachEveryProxyReason keeps the four proxy scenarios honest:
360	// each state of the Proxy row is produced by a real Run, so its guidance is
361	// reachable and not just written.
362	func TestTheBatteriesReachEveryProxyReason(t *testing.T) {
363		seen := map[Reason]bool{}
364		for _, c := range produced(t) {
365			if c.ID == CheckProxy {
366				seen[c.Reason] = true
367			}
368		}
369		for _, r := range []Reason{
370			ReasonProxyNone, ReasonProxyConfigured, ReasonProxyExcluded, ReasonProxyLoopback, ReasonProxyInvalid,
371		} {
372			if !seen[r] {
373				t.Errorf("no scenario of the battery produces a proxy row with reason %q", r)
374			}
375		}
376	}
