202	// TestEveryCheckAScenarioProducesIsExplained is the contract: no state a user
203	// can reach leaves them reading a verdict with nothing telling them what it
204	// means. It is behavioural rather than a list of pairs, because a list would
205	// have to be kept in step with the stages by hand.
206	func TestEveryCheckAScenarioProducesIsExplained(t *testing.T) {
207		for _, s := range batteries(t) {
208			res, err := Run(context.Background(), s.tg, s.env, DefaultSettings())
209			if err != nil {
210				t.Fatalf("%s: %v", s.name, err)
211			}
212			for _, c := range res.All() {
213				e := Explain(c)
214				if strings.Contains(e.Means, "No guidance is written") {
215					t.Errorf("%s: %s at %s (reason %q) fell through to the fallback",
216						s.name, c.ID, c.Verdict, c.Reason)
217				}
218				if strings.TrimSpace(e.Means) == "" {
219					t.Errorf("%s: %s at %s has no explanation", s.name, c.ID, c.Verdict)
220				}
221				if e.Observed != c.Summary {
222					t.Errorf("%s: %s restates the observation instead of carrying it", s.name, c.ID)
223				}
224			}
225		}
226	}
