342	// TestNoTwoRowsShareTheirText catches the copy-paste that makes a table look
343	// complete while saying the same thing everywhere.
344	func TestNoTwoRowsShareTheirText(t *testing.T) {
345		seen := map[string]string{}
346		for _, g := range explanations {
347			key := string(g.check) + "/" + g.verdict.String() + "/" + string(g.reason)
348			if prev, ok := seen[g.means]; ok {
349				t.Errorf("%s repeats the explanation of %s", key, prev)
350			}
351			seen[g.means] = key
352			if len(g.means) < 40 {
353				t.Errorf("%s explains in %d characters, which is a restatement rather than a meaning",
354					key, len(g.means))
355			}
356		}
357	}
